//! The operator's editorial account (ADR-0002): the one library account,
//! marked by the operator, under which it shares the content it makes
//! itself. Its items are signed with `author.editorial` true, shown as the
//! software's publisher's, and each version says whether it was generated by
//! AI and who read it before it was shared (`docs/specs/interface-v1.md`,
//! Shares). The Selection mark is in [`selection`].

pub(crate) mod selection;

use jiff::Timestamp;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use sqlx::PgPool;

use crate::shares::ShareRefusal;

/// Why the editorial account could not be marked.
#[derive(Debug)]
pub enum EditorialError {
    /// The Minute Jar account has no library account.
    NoAccount,
    /// Another library account is the editorial account already.
    AnotherEditorialAccount,
    Database(sqlx::Error),
}

impl From<sqlx::Error> for EditorialError {
    fn from(error: sqlx::Error) -> Self {
        EditorialError::Database(error)
    }
}

/// Marks at `now` the library account on the Minute Jar account `subject`
/// as the editorial account. Marking it again changes nothing.
pub(crate) async fn mark(
    pool: &PgPool,
    subject: &str,
    now: Timestamp,
) -> Result<(), EditorialError> {
    let account: Option<(i64,)> =
        sqlx::query_as("SELECT id FROM library_accounts WHERE subject = $1")
            .bind(subject)
            .fetch_optional(pool)
            .await?;
    let Some((account,)) = account else {
        return Err(EditorialError::NoAccount);
    };
    let marked: Option<(i64,)> = sqlx::query_as("SELECT account FROM editorial_account")
        .fetch_optional(pool)
        .await?;
    match marked {
        Some((marked,)) if marked == account => Ok(()),
        Some(_) => Err(EditorialError::AnotherEditorialAccount),
        None => {
            sqlx::query(
                "INSERT INTO editorial_account (account, marked_at) VALUES ($1, $2)
                 ON CONFLICT DO NOTHING",
            )
            .bind(account)
            .bind(now.as_second())
            .execute(pool)
            .await?;
            Ok(())
        }
    }
}

/// Ends the mark of the library account on `subject`; answers whether it
/// had it. The versions it shared stay signed as they were.
pub(crate) async fn unmark(pool: &PgPool, subject: &str) -> Result<bool, sqlx::Error> {
    let removed = sqlx::query(
        "DELETE FROM editorial_account AS e USING library_accounts AS a
         WHERE a.id = e.account AND a.subject = $1",
    )
    .bind(subject)
    .execute(pool)
    .await?;
    Ok(removed.rows_affected() > 0)
}

/// What a share from the editorial account says of how it was made and read.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Marks {
    pub ai_generated: bool,
    pub read: Read,
}

/// Who read the item before it was shared, and when.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Read {
    pub by: Reader,
    /// The moderator's handle, when a moderator read it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub handle: Option<String>,
    /// RFC 3339.
    pub at: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum Reader {
    Moderator,
    Operator,
}

/// The marks of a share once checked: the moderator's handle as the
/// operator named them, or `None` for the operator.
#[derive(Debug, Clone)]
pub(crate) struct Checked {
    ai_generated: bool,
    reader: Option<String>,
    read_at: Timestamp,
}

/// Checks the marks a share from `account` carries at `now`: the editorial
/// account's shares must say how they were made and who read them, and no
/// other account's may.
pub(crate) async fn check(
    pool: &PgPool,
    account: i64,
    marks: Option<&Marks>,
    now: Timestamp,
) -> Result<Option<Checked>, ShareRefusal> {
    let (editorial,): (bool,) =
        sqlx::query_as("SELECT EXISTS (SELECT 1 FROM editorial_account WHERE account = $1)")
            .bind(account)
            .fetch_one(pool)
            .await?;
    let marks = match (editorial, marks) {
        (false, None) => return Ok(None),
        (false, Some(_)) => return Err(ShareRefusal::NotEditorial),
        (true, None) => return Err(ShareRefusal::ReadingRequired),
        (true, Some(marks)) => marks,
    };
    let read_at = marks
        .read
        .at
        .parse::<Timestamp>()
        .ok()
        .filter(|at| *at <= now)
        .ok_or(ShareRefusal::BadReading)?;
    let reader = match (marks.read.by, &marks.read.handle) {
        (Reader::Operator, None) => None,
        (Reader::Moderator, Some(handle)) => {
            let named: Option<(String,)> =
                sqlx::query_as("SELECT handle FROM moderators WHERE lower(handle) = lower($1)")
                    .bind(handle.trim())
                    .fetch_optional(pool)
                    .await?;
            Some(named.ok_or(ShareRefusal::BadReading)?.0)
        }
        _ => return Err(ShareRefusal::BadReading),
    };
    Ok(Some(Checked {
        ai_generated: marks.ai_generated,
        reader,
        read_at,
    }))
}

/// Records the marks of a version the editorial account published.
pub(crate) async fn record(
    pool: &PgPool,
    item: &str,
    version: u32,
    checked: &Checked,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "INSERT INTO editorial_readings (item, version, ai_generated, reader, read_at)
         VALUES ($1, $2, $3, $4, $5) ON CONFLICT DO NOTHING",
    )
    .bind(item)
    .bind(version as i32)
    .bind(checked.ai_generated)
    .bind(&checked.reader)
    .bind(checked.read_at.as_second())
    .execute(pool)
    .await?;
    Ok(())
}

/// Records the marks a held share kept, once a moderator published it:
/// they were checked when it was shared.
pub(crate) async fn record_held(
    pool: &PgPool,
    item: &str,
    version: u32,
    marks: Option<&Marks>,
) -> Result<(), sqlx::Error> {
    let Some(marks) = marks else {
        return Ok(());
    };
    let Ok(read_at) = marks.read.at.parse::<Timestamp>() else {
        return Ok(());
    };
    let checked = Checked {
        ai_generated: marks.ai_generated,
        reader: match marks.read.by {
            Reader::Operator => None,
            Reader::Moderator => marks.read.handle.clone(),
        },
        read_at,
    };
    record(pool, item, version, &checked).await
}

/// The marks of `version` of `item` as the item page answers them, `null`
/// for a version the editorial account did not share.
pub(crate) async fn marks(pool: &PgPool, item: &str, version: u32) -> Result<Value, sqlx::Error> {
    let row: Option<(bool, Option<String>, i64)> = sqlx::query_as(
        "SELECT ai_generated, reader, read_at FROM editorial_readings
         WHERE item = $1 AND version = $2",
    )
    .bind(item)
    .bind(version as i32)
    .fetch_optional(pool)
    .await?;
    Ok(match row {
        None => Value::Null,
        Some((ai_generated, reader, read_at)) => {
            let at =
                crate::contract::time(Timestamp::from_second(read_at).expect("a stored instant"));
            let read = match reader {
                Some(handle) => json!({"by": "moderator", "handle": handle, "at": at}),
                None => json!({"by": "operator", "at": at}),
            };
            json!({"ai_generated": ai_generated, "read": read})
        }
    })
}
